function save(){localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(UI_KEY,JSON.stringify({...ui,forge:'idle',busy:false}));syncState(cloudStore,state,window.promptforgeSupabase).then(result=>{if(result.reason==='authentication-required')console.info('[Cloud Store] Sign in required before cloud sync');}).catch(error=>console.error('[Cloud Store] Sync failed',error))}
function toast(message){const target=$('toast');target.textContent=message;target.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>target.classList.remove('show'),1800)}
function mutate(change,{clearTake=true}={}){state={...change(state),dirty:true,...(clearTake?{selectedTake:null}:{})};render()}
