function renderWorkspaceShell(){const root=$('workspaceRoot');root.querySelector('.workspace-view')?.remove();root.querySelector('.studio-head').classList.toggle('hidden',activeWorkspace!=='create');document.querySelectorAll('[data-workspace]').forEach(button=>{const active=button.dataset.workspace===activeWorkspace;button.classList.toggle('nav-active',active);if(button.closest('.topbar'))button.classList.toggle('active',active);button.toggleAttribute('aria-current',active)});if(activeWorkspace!=='create')root.querySelectorAll(':scope > *:not(.workspace-view):not(.studio-head)').forEach(node=>node.classList.add('hidden'));else root.querySelectorAll(':scope > *').forEach(node=>node.classList.remove('hidden'))}
function renderCharactersWorkspace(view){const characters=state.characters||[];view.innerHTML=`<header class="workspace-head"><div><div class="eyebrow">CHARACTER LIBRARY · ${characters.length} SAVED</div><h1>Characters</h1><p>Keep identity foundations reusable, stable and separate from Studio direction.</p></div><button class="primary" id="newCharacterBtn">＋ New Character</button></header>${characters.length?`<div class="workspace-grid character-roster">${characters.map(character=>`<article class="panel character-card ${character.id===state.activeCharacterId?'selected':''} ${character.archived?'archived':''}"><div class="character-card-head"><div><span class="library-kicker">${character.id===state.activeCharacterId?'ACTIVE CHARACTER':'CHARACTER CORE'}</span><h2>${escape(character.name)}</h2></div><span class="state-badge">Revision ${character.revision}</span></div><p>${escape(character.identity?.occupation||'Unspecified occupation')} · ${escape(character.identity?.location||'Unspecified location')}</p><small>Stable ID ${escape(character.id)} · ${(character.interests||[]).length} interests · ${(character.references||[]).length} references${character.archived?' · Archived':''}</small><div class="character-card-actions"><button data-character-open="${escape(character.id)}" ${character.archived?'disabled':''}>Open in Studio</button><button data-character-edit="${escape(character.id)}">Edit Core</button><button data-character-archive="${escape(character.id)}">${character.archived?'Restore':'Archive'}</button><button data-character-delete="${escape(character.id)}">Delete</button></div></article>`).join('')}</div>`:'<div class="panel library-empty"><b>No saved Characters yet</b><span>Create a Character Core to start your roster.</span></div>'}`;view.querySelector('#newCharacterBtn').onclick=event=>openCore(event.currentTarget,{mode:'new'});view.querySelectorAll('[data-character-open]').forEach(button=>button.onclick=()=>{state=switchCharacter(state,button.dataset.characterOpen);goWorkspace('create');toast('Active Character opened')});view.querySelectorAll('[data-character-edit]').forEach(button=>button.onclick=()=>{state=switchCharacter(state,button.dataset.characterEdit);openCore(button)});view.querySelectorAll('[data-character-archive]').forEach(button=>button.onclick=()=>{const id=button.dataset.characterArchive;state=archiveCharacter(state,id,!state.characters.find(item=>item.id===id)?.archived);render();toast('Character roster updated')});view.querySelectorAll('[data-character-delete]').forEach(button=>button.onclick=()=>{const id=button.dataset.characterDelete;const character=state.characters.find(item=>item.id===id);if(!character)return;if((state.takes||[]).some(take=>take.characterId===id)&&!window.confirm(`${character.name} owns Takes. Permanently delete the character and its Takes?`))return;try{state=deleteCharacter(state,id,{force:true});render();toast('Character deleted')}catch(error){toast(error.message)}})}
function enhanceDuplicateActions(){document.querySelectorAll('.character-card').forEach(card=>{const id=card.querySelector('[data-character-edit]')?.dataset.characterEdit;if(!id||card.querySelector('[data-character-duplicate]'))return;const button=document.createElement('button');button.textContent='Duplicate';button.dataset.characterDuplicate=id;button.setAttribute('aria-label',`Duplicate ${state.characters.find(character=>character.id===id)?.name||'character'}`);button.onclick=()=>{state=duplicateCharacter(state,id);goWorkspace('characters');toast('Character duplicated without Takes or prompts')};card.querySelector('.character-card-actions')?.insertBefore(button,card.querySelector('[data-character-delete]'))})}
function renderProjectsWorkspace(view){const projects=state.projects||[],active=projects.find(project=>project.id===state.activeProjectId)||null,characterName=id=>state.characters.find(character=>character.id===id)?.name||'Unavailable Character';view.innerHTML=`<header class="workspace-head"><div><div class="eyebrow">PROJECT LIBRARY · ${projects.length} SAVED</div><h1>Projects</h1><p>Organize references without changing Character or Take ownership.</p></div><button class="primary" id="newProjectBtn">＋ New Project</button></header>${projects.length?`<div class="project-layout"><div class="workspace-grid character-roster">${projects.map(project=>`<article class="panel character-card ${project.id===active?.id?'selected':''} ${project.status==='archived'?'archived':''}"><div class="character-card-head"><div><span class="library-kicker">${project.status.toUpperCase()}</span><h2>${escape(project.name)}</h2></div></div><p>${escape(project.brief||'No creative brief yet.')}</p><small>${project.characterIds.length} characters · ${project.takeIds.length} Takes · Updated ${new Date(project.updatedAt).toLocaleDateString()}</small><div class="character-card-actions"><button data-project-open="${project.id}">View Project</button><button data-project-archive="${project.id}">${project.status==='archived'?'Restore':'Archive'}</button><button data-project-delete="${project.id}">Delete</button></div></article>`).join('')}</div>${active?`<aside class="panel project-detail"><div class="character-card-head"><div><span class="library-kicker">PROJECT DETAIL</span><h2>${escape(active.name)}</h2></div><button data-project-edit="${active.id}">Edit</button></div><p>${escape(active.brief||'No creative brief yet.')}</p><div class="project-direction"><b>Direction</b><span>${escape(active.direction.notes||active.direction.sceneIntent||active.direction.styleIntent||'No project direction set.')}</span></div><h3>Characters</h3>${state.characters.map(character=>`<div class="project-reference"><span>${escape(character.name)}</span><div>${active.characterIds.includes(character.id)?`<button data-project-character-open="${character.id}">Open in Studio</button><button data-project-character-remove="${character.id}">Remove</button>`:`<button data-project-character-add="${character.id}">Add</button>`}</div></div>`).join('')||'<p>No Characters available.</p>'}<h3>Attached Takes</h3>${state.takes.map(take=>`<div class="project-reference"><span>${escape(characterName(take.characterId))} · ${escape(take.variationReason||take.id)}</span><div>${active.takeIds.includes(take.id)?`<button data-project-take-open="${take.id}">Open Take</button><button data-project-take-remove="${take.id}">Detach</button>`:`<button data-project-take-add="${take.id}">Attach</button>`}</div></div>`).join('')||'<p>No Takes available.</p>'}</aside>`:''}</div>`:'<div class="panel library-empty"><b>No Projects yet</b><span>Create a workspace to organize existing Characters and Takes.</span></div>'}`;$('newProjectBtn').onclick=()=>{const name=window.prompt('Project name','New Project');if(name?.trim()){state=createProject(state,{name:name.trim()});render()}};view.querySelectorAll('[data-project-open]').forEach(button=>button.onclick=()=>{state={...state,activeProjectId:button.dataset.projectOpen};render()});view.querySelectorAll('[data-project-archive]').forEach(button=>button.onclick=()=>{const project=projects.find(item=>item.id===button.dataset.projectArchive);state=archiveProject(state,project.id,project.status!=='archived');render()});view.querySelectorAll('[data-project-delete]').forEach(button=>button.onclick=()=>{if(window.confirm('Delete this Project? Characters and Takes will remain untouched.')){state=deleteProject(state,button.dataset.projectDelete);render()}});view.querySelector('[data-project-edit]')?.addEventListener('click',()=>{const name=window.prompt('Project name',active.name),brief=window.prompt('Creative brief',active.brief);if(name!==null&&brief!==null){state=updateProject(state,active.id,{name:name.trim()||active.name,brief:brief.trim()});render()}});view.querySelectorAll('[data-project-character-add]').forEach(button=>button.onclick=()=>{state=attachCharacter(state,active.id,button.dataset.projectCharacterAdd);render()});view.querySelectorAll('[data-project-character-remove]').forEach(button=>button.onclick=()=>{state=detachCharacter(state,active.id,button.dataset.projectCharacterRemove);render()});view.querySelectorAll('[data-project-character-open]').forEach(button=>button.onclick=()=>{state=openProjectCharacter(state,button.dataset.projectCharacterOpen);goWorkspace('create')});view.querySelectorAll('[data-project-take-add]').forEach(button=>button.onclick=()=>{state=attachTake(state,active.id,button.dataset.projectTakeAdd);render()});view.querySelectorAll('[data-project-take-remove]').forEach(button=>button.onclick=()=>{state=detachTake(state,active.id,button.dataset.projectTakeRemove);render()});view.querySelectorAll('[data-project-take-open]').forEach(button=>button.onclick=()=>{state=openProjectTake(state,button.dataset.projectTakeOpen);goWorkspace('create')})}

const INSPIRATION_DOMAIN_META=Object.freeze({
  mood:{label:'Mood',glyph:'♧',color:'#8f6ab4'},
  setting:{label:'Setting',glyph:'△',color:'#727ca8'},
  activity:{label:'Activity',glyph:'◴',color:'#656d98'},
  wardrobe:{label:'Wardrobe',glyph:'♜',color:'#927687'},
  camera:{label:'Camera',glyph:'▣',color:'#80669d'},
  lighting:{label:'Lighting',glyph:'☼',color:'#b18163'},
  style:{label:'Style',glyph:'✦',color:'#76588f'}
});

function inspirationWheelBackground(weights){let cursor=0;const stops=[];for(const domain of INFLUENCE_DOMAINS){const end=cursor+weights[domain];stops.push(`${INSPIRATION_DOMAIN_META[domain].color} ${cursor}% ${end}%`);cursor=end}return `conic-gradient(from -90deg,${stops.join(',')})`}
function persistInspirationLocal(){localStorage.setItem(KEY,JSON.stringify(state))}
function inspirationConceptMarkup(inspiration){const resolved=new Map((inspiration.direction?.concepts||[]).map(concept=>[String(concept.input).toLowerCase(),concept]));return inspiration.concepts.map((concept,index)=>{const label=typeof concept==='object'?(concept.label||concept.id):concept,match=resolved.get(String(label).toLowerCase()),status=match&&!match.known?' unknown':'';return `<span class="inspiration-concept${status}">${escape(label)}${status?'<small>unmapped</small>':''}<button type="button" data-inspiration-remove="${index}" aria-label="Remove ${escape(label)}">×</button></span>`}).join('')||'<span class="concept-empty">Concepts appear here as you type.</span>'}
function renderInspirationConcepts(view){const inspiration=normalizeInspirationState(state.inspirationState),target=view.querySelector('#inspirationConcepts');if(target)target.innerHTML=inspirationConceptMarkup(inspiration);view.querySelector('#inspirationIdeaCount').textContent=`${inspiration.rawIdea.length}/300`;view.querySelector('#buildDirectionBtn').disabled=!inspiration.concepts.length;view.querySelectorAll('[data-inspiration-remove]').forEach(button=>button.onclick=()=>{state={...state,inspirationState:removeInspirationConcept(state.inspirationState,Number(button.dataset.inspirationRemove))};persistInspirationLocal();render()})}
function refreshInspirationWeights(view){const weights=state.inspirationState.weights,total=Object.values(weights).reduce((sum,value)=>sum+value,0),wheel=view.querySelector('#inspirationWheel');wheel.style.background=inspirationWheelBackground(weights);wheel.setAttribute('aria-label',`Creative influence wheel. ${INFLUENCE_DOMAINS.map(domain=>`${INSPIRATION_DOMAIN_META[domain].label} ${weights[domain]} percent`).join(', ')}. Total ${total} percent.`);let cursor=0;for(const domain of INFLUENCE_DOMAINS){const value=weights[domain],angle=(cursor+value/2)/100*Math.PI*2-Math.PI/2,label=view.querySelector(`[data-wheel-domain="${domain}"]`);label.style.left=`${50+34*Math.cos(angle)}%`;label.style.top=`${50+34*Math.sin(angle)}%`;label.querySelector('strong').textContent=`${value}%`;const input=view.querySelector(`[data-inspiration-weight="${domain}"]`);input.value=String(value);input.nextElementSibling.value=`${value}%`;cursor+=value}view.querySelector('#inspirationTotal').textContent=`${total}%`;view.querySelector('#inspirationReady').textContent=total===100?'DIRECTION READY':'ADJUST WEIGHTS';view.querySelector('#inspirationReady').classList.toggle('ready',total===100)}

function renderInspirationWorkspace(view){
  const inspiration=normalizeInspirationState(state.inspirationState),preview=directionPreviewData(inspiration.direction),projects=(state.projects||[]).filter(project=>project.status!=='archived'),projectId=projects.some(project=>project.id===state.activeProjectId)?state.activeProjectId:projects[0]?.id;
  state={...state,inspirationState:inspiration};
  const previewRows=preview.rows.map(row=>`<div class="direction-row"><span>${escape(row.label)}</span><div><b>${escape(row.value)}</b><small>Suggested by: ${escape(row.reason)}</small></div></div>`).join(''),draftSignals=inspiration.source?.draftSignals||[],signalKey=(takeId,domain)=>`${takeId}:${domain}`,selectedSignals=new Set(draftSignals.map(signal=>signalKey(signal.takeId,signal.domain))),takeCards=(state.takes||[]).map((take,index)=>{const domains=availableTakeSemanticDomains(take),selected=domains.filter(domain=>selectedSignals.has(signalKey(take.id,domain)));if(!domains.length)return `<article class="take-source unavailable"><b>Take ${String(index+1).padStart(2,'0')} unavailable</b><small>No stored semantic signals</small></article>`;const character=(state.characters||[]).find(item=>item.id===take.characterId)||state.character,summary=domains.slice(0,4).map(domain=>take.semantic[domain]?.[0]?.label).filter(Boolean).join(' · ');return `<article class="take-source"><header><b>Take ${String(index+1).padStart(2,'0')} · ${escape(character?.name||'Unknown character')}</b><small>${escape(take.variationReason||'Saved Take')}</small></header><p>${escape(summary)}</p><div class="take-signal-grid">${domains.map(domain=>`<label><input type="checkbox" data-take-signal="${take.id}" data-take-domain="${domain}" ${selectedSignals.has(signalKey(take.id,domain))?'checked':''}> ${escape(INSPIRATION_DOMAIN_META[domain]?.label||domain)}</label>`).join('')}</div><button type="button" data-take-use-all="${take.id}">${selected.length===domains.length?'Clear all':'Use all'}</button></article>`}).join('')||'<p class="preview-empty">No Takes are available yet.</p>',takePicker=inspiration.mode==='takes'?`<section class="inspiration-panel take-picker"><div class="inspiration-panel-title"><h2>From Takes</h2><span>Select what to borrow</span></div><p class="take-picker-copy">Choose specific creative signals. Takes remain unchanged.</p><div class="take-source-list">${takeCards}</div><button id="buildFromTakesBtn" class="primary" type="button" ${draftSignals.length?'':'disabled'}>Build Inspiration from ${draftSignals.length} signal${draftSignals.length===1?'':'s'} →</button></section>`:'';
  view.innerHTML=`<div class="inspiration-shell">
    <header class="inspiration-head"><div><div class="eyebrow">INSPIRATION / CREATE</div><h1>Inspiration</h1><p>Turn incomplete ideas into structured creative direction.</p></div><blockquote>“Ideas are the beginning<br>of something beautiful.”</blockquote></header>
    <nav class="inspiration-modes" aria-label="Inspiration modes"><button class="${inspiration.mode==='takes'?'':'active'}" type="button" data-inspiration-mode="create">✎ <span>Create</span></button><button class="${inspiration.mode==='takes'?'active':''}" type="button" data-inspiration-mode="takes">◫ <span>From Takes</span></button></nav>
    <div class="inspiration-layout">
      <aside class="inspiration-left">
        ${takePicker}<section class="inspiration-panel idea-panel"><div class="inspiration-panel-title"><h2>Your Idea</h2><span>Typed concepts</span></div><textarea id="inspirationIdea" maxlength="300" rows="5" placeholder="rainy, London, quiet, bookshop, warm lighting, cinematic">${escape(inspiration.rawIdea)}</textarea><div class="idea-meta"><span id="inspirationIdeaCount">${inspiration.rawIdea.length}/300</span><span>Commas or new lines</span></div><div class="inspiration-concepts" id="inspirationConcepts">${inspirationConceptMarkup(inspiration)}</div></section>
        <section class="inspiration-panel quick-prompts"><div class="inspiration-panel-title"><h2>Quick Concepts</h2><span>Append, never replace</span></div><div>${INSPIRATION_STARTERS.map(concept=>`<button type="button" data-inspiration-starter="${escape(concept)}">＋ ${escape(concept)}</button>`).join('')}</div><label>Direction seed<input id="inspirationSeed" value="${escape(inspiration.seed)}" maxlength="60"></label></section>
      </aside>
      <main class="inspiration-centre">
        <section class="wheel-stage" aria-labelledby="wheelTitle"><div class="wheel-heading"><span>100% INFLUENCE BUDGET</span><h2 id="wheelTitle">Shape what matters most</h2><p>Move a slider and the remaining domains rebalance proportionally.</p></div><div class="inspiration-wheel" id="inspirationWheel" role="img">${INFLUENCE_DOMAINS.map(domain=>`<span class="wheel-domain" data-wheel-domain="${domain}"><i>${INSPIRATION_DOMAIN_META[domain].glyph}</i>${INSPIRATION_DOMAIN_META[domain].label}<strong>${inspiration.weights[domain]}%</strong></span>`).join('')}<div class="wheel-core"><b id="inspirationTotal">100%</b><span id="inspirationReady" class="ready">DIRECTION READY</span><i>✦</i></div></div><div class="wheel-actions"><button id="resetInspirationBtn" type="button">Reset</button><button id="buildDirectionBtn" type="button" class="primary" ${inspiration.concepts.length?'':'disabled'}>Build Direction <span>→</span></button></div></section>
        <section class="inspiration-alternatives"><span>HOW IT WORKS</span><div><article><b>01</b><h3>Add concepts</h3><p>Keep broad ideas and unknown words visible.</p></article><article><b>02</b><h3>Balance influence</h3><p>Six creative domains always share exactly 100%.</p></article><article><b>03</b><h3>Build direction</h3><p>Relationships and compatibility rank real candidates.</p></article></div></section>
      </main>
      <aside class="inspiration-right">
        <section class="inspiration-panel weight-details"><div class="inspiration-panel-title"><h2>Weighting Details</h2><span>Always 100%</span></div>${INFLUENCE_DOMAINS.map(domain=>`<label><i>${INSPIRATION_DOMAIN_META[domain].glyph}</i><span>${INSPIRATION_DOMAIN_META[domain].label}</span><input type="range" min="0" max="100" step="1" value="${inspiration.weights[domain]}" data-inspiration-weight="${domain}" aria-label="${INSPIRATION_DOMAIN_META[domain].label} influence"><output>${inspiration.weights[domain]}%</output></label>`).join('')}</section>
        <section class="inspiration-panel direction-preview" aria-live="polite"><div class="inspiration-panel-title"><h2>Direction Preview</h2><span>${inspiration.direction?'Structured result':'Awaiting build'}</span></div>${inspiration.direction?`<h3>${escape(preview.title)}</h3><p class="direction-kicker">Resolved from ${inspiration.concepts.length} concept${inspiration.concepts.length===1?'':'s'} · Seed ${escape(inspiration.seed)}</p><div class="direction-rows">${previewRows||'<p class="preview-empty">No mapped recommendations yet. Refine the idea or add a known concept.</p>'}</div>${preview.unknownConcepts.length?`<div class="unknown-note"><b>Kept as entered</b><span>${preview.unknownConcepts.map(escape).join(' · ')}</span></div>`:''}`:'<div class="preview-placeholder"><span>✧</span><b>No direction built yet</b><p>Add a few ideas, tune the balance, then build an explainable direction.</p></div>'}<div class="direction-actions"><button id="refineDirectionBtn" type="button" ${inspiration.direction?'':'disabled'}>Refine</button><div class="project-action"><select id="inspirationProject" aria-label="Project for this direction" ${projects.length?'':'disabled'}>${projects.length?projects.map(project=>`<option value="${escape(project.id)}" ${project.id===projectId?'selected':''}>${escape(project.name)}</option>`).join(''):'<option>No active Projects</option>'}</select><button id="addDirectionProjectBtn" type="button" ${inspiration.direction&&projects.length?'':'disabled'}>Add to Project</button></div><button id="sendDirectionStudioBtn" type="button" class="primary" ${inspiration.direction?'':'disabled'}>Send to Studio →</button></div></section>
      </aside>
    </div>
  </div>`;
  refreshInspirationWeights(view);
  view.querySelectorAll('[data-inspiration-mode]').forEach(button=>button.onclick=()=>{state={...state,inspirationState:{...state.inspirationState,mode:button.dataset.inspirationMode}};render()});
  view.querySelectorAll('[data-take-signal]').forEach(input=>input.onchange=()=>{const signal={takeId:input.dataset.takeSignal,characterId:(state.takes||[]).find(take=>take.id===input.dataset.takeSignal)?.characterId||null,domain:input.dataset.takeDomain},next=input.checked?[...draftSignals,signal]:draftSignals.filter(item=>signalKey(item.takeId,item.domain)!==signalKey(signal.takeId,signal.domain));state={...state,inspirationState:{...state.inspirationState,source:{...state.inspirationState.source,draftSignals:next}}};render()});
  view.querySelectorAll('[data-take-use-all]').forEach(button=>button.onclick=()=>{const take=(state.takes||[]).find(item=>item.id===button.dataset.takeUseAll),domains=availableTakeSemanticDomains(take),all=domains.every(domain=>selectedSignals.has(signalKey(take.id,domain))),remaining=draftSignals.filter(signal=>signal.takeId!==take.id),next=all?remaining:[...remaining,...domains.map(domain=>({takeId:take.id,characterId:take.characterId,domain}))];state={...state,inspirationState:{...state.inspirationState,source:{...state.inspirationState.source,draftSignals:next}}};render()});
  view.querySelector('#buildFromTakesBtn')?.addEventListener('click',()=>{state={...state,inspirationState:buildInspirationFromTakeSignals(state.inspirationState,state.takes,draftSignals)};persistInspirationLocal();render();toast(`Loaded ${draftSignals.length} Take signal${draftSignals.length===1?'':'s'} into Inspiration`)});
  view.querySelector('#inspirationIdea').oninput=event=>{state={...state,inspirationState:setInspirationIdea(state.inspirationState,event.target.value)};persistInspirationLocal();renderInspirationConcepts(view)};
  view.querySelectorAll('[data-inspiration-starter]').forEach(button=>button.onclick=()=>{state={...state,inspirationState:appendInspirationConcept(state.inspirationState,button.dataset.inspirationStarter)};render();toast(`${button.dataset.inspirationStarter} added`)});
  view.querySelector('#inspirationSeed').oninput=event=>{state={...state,inspirationState:{...state.inspirationState,seed:event.target.value||'inspiration-1'}};persistInspirationLocal()};
  view.querySelectorAll('[data-inspiration-weight]').forEach(input=>{input.oninput=event=>{state={...state,inspirationState:{...state.inspirationState,weights:rebalanceInspirationWeights(state.inspirationState.weights,event.target.dataset.inspirationWeight,event.target.value)}};persistInspirationLocal();refreshInspirationWeights(view)}});
  view.querySelector('#resetInspirationBtn').onclick=()=>{state={...state,inspirationState:resetInspirationWeights(state.inspirationState)};render();toast('Influence weights reset')};
  view.querySelector('#buildDirectionBtn').onclick=()=>{try{state={...state,inspirationState:buildInspirationDirection(state.inspirationState)};render();toast('Creative Direction built')}catch(error){console.error('[Inspiration]',error);toast('Direction could not be built')}};
  view.querySelector('#refineDirectionBtn').onclick=()=>{const input=view.querySelector('#inspirationIdea');input.scrollIntoView({behavior:motionOK()?'smooth':'auto',block:'center'});input.focus();toast('Direction preserved while you refine')};
  view.querySelector('#addDirectionProjectBtn').onclick=()=>{const select=view.querySelector('#inspirationProject');state=addInspirationToProject(state,select.value,state.inspirationState.direction);render();toast('Direction added to Project')};
  view.querySelector('#sendDirectionStudioBtn').onclick=()=>{state=applyInspirationToStudio(state,state.inspirationState.direction);goWorkspace('create');toast('Direction applied to Studio working state')};
}

function renderWorkspaceView(){const root=$('workspaceRoot'),view=document.createElement('div');view.className='workspace-view';const meta=workspaceMeta[activeWorkspace]||workspaceMeta.projects;if(activeWorkspace==='inspiration'){root.append(view);renderInspirationWorkspace(view);return}if(activeWorkspace==='account'){root.append(view);renderAccountWorkspace(view);return}if(activeWorkspace==='characters'){root.append(view);renderCharactersWorkspace(view);return}if(activeWorkspace==='projects'){root.append(view);renderProjectsWorkspace(view);return}let body='';if(activeWorkspace==='scenes')body=`<div class="workspace-grid">${SCENE_OPTIONS.map(scene=>`<button type="button" class="panel catalogue-card" data-scene-select="${escape(scene.id)}"><h2>${icon(SCENE_ICONS[scene.id]||'scene',scene.name)} ${escape(scene.name)}</h2><p>${escape(scene.location)}</p><small>${escape(scene.activity)}</small></button>`).join('')}</div>`;else if(activeWorkspace==='library'){root.append(view);renderLibraryWorkspace(view);return}else if(activeWorkspace==='tools')body='<div class="panel"><h2>Resolver Inspector</h2><p>Inspect deterministic Style resolution in Create.</p><button class="primary" id="toolsInspect">Open Inspector</button></div>';else body=`<div class="panel"><h2>${meta[0]}</h2><p>${meta[2]}</p><div class="empty-copy"><b>${meta[1]} is ready for the next milestone</b><span>This workspace keeps your Studio state intact.</span></div></div>`;view.innerHTML=`<div class="studio-head"><div class="eyebrow">PROMPTFORGE WORKSPACE</div><h1>${meta[0]}</h1><p>${meta[2]}</p></div>${body}`;root.append(view);$('toolsInspect')?.addEventListener('click',()=>{goWorkspace('create');setTimeout(inspect,0)})}

function countLabel(value,singular,plural=singular+'s'){return `${value} ${value===1?singular:plural}`}
const accountDate=value=>{const date=new Date(value);return Number.isNaN(date.valueOf())?'':date.toLocaleDateString(undefined,{month:'short',day:'numeric'})};
function accountViewModel(summary={},user=null){
  const localTakes=state.takes||[],takes=(summary.recentTakes?.length?summary.recentTakes:localTakes).map(take=>({...take,createdAt:take.created_at||take.createdAt,image:take.image||take.image_url||null,stateSnapshot:take.state_snapshot||take.stateSnapshot||{}}));
  const influences=new Map();for(const take of takes){for(const item of take.stateSnapshot?.styleMix?.influences||[])influences.set(item.packId,(influences.get(item.packId)||0)+(Number(item.weight)||1))}if(!influences.size)for(const item of state.styleMix?.influences||[])influences.set(item.packId,Number(item.weight)||1);
  const styleTotal=[...influences.values()].reduce((sum,value)=>sum+value,0)||1,styles=[...influences.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([id,value],index)=>({name:STYLE_PACK_LIST.find(pack=>pack.id===id)?.name||id,value,percent:Math.round(value/styleTotal*100),color:['#f39bc8','#c891f0','#947cff','#63c9be','#f3c883'][index]}));
  const now=new Date(),activity=Array.from({length:14},(_,index)=>{const day=new Date(now);day.setHours(0,0,0,0);day.setDate(day.getDate()-(13-index));return {day,label:day.toLocaleDateString(undefined,{weekday:'short'}),count:0}});for(const take of takes){const stamp=new Date(take.createdAt);const row=activity.find(item=>stamp>=item.day&&stamp<new Date(item.day.getTime()+86400000));if(row)row.count++}
  const profile=summary.profile||{},reference=state.character?.references?.find(item=>item.image)?.image,takeImage=takes.find(item=>item.image)?.image;
return {name:profile.display_name||state.character?.name||user?.email?.split('@')[0]||'Creator',email:user?.email||'',memberSince:profile.created_at||user?.created_at||state.character?.createdAt,avatar:profile.avatar_url||reference||takeImage||'',characters:Number(summary.characters??(state.character?1:0)),takes:Number(summary.takes??takes.length),prompts:Number(summary.prompts??state.compiledPrompts?.length??0),projects:Number(summary.projects??state.projects?.length??0),favorites:Number(summary.favorites||0),hours:Math.max(0,Math.round(takes.length*.4)),recent:takes.slice(0,4),activity,styles,cloud:Boolean(user)};
}
function accountBars(rows){const max=Math.max(1,...rows.map(row=>row.count));return rows.map((row,index)=>`<span class="activity-bar" style="--bar:${Math.max(8,Math.round(row.count/max*100))}%"><i></i>${index%3===0?`<small>${escape(row.label)}</small>`:''}<b class="sr-only">${row.count} creations on ${escape(accountDate(row.day))}</b></span>`).join('')}
function styleDonut(styles){let offset=0;const stops=styles.length?styles.map(item=>{const start=offset;offset+=item.percent;return `${item.color} ${start}% ${offset}%`}).join(','):'#314055 0 100%';return `<div class="style-donut" style="--segments:conic-gradient(${stops})"><strong>${styles.reduce((sum,item)=>sum+item.value,0)}</strong><span>Total uses</span></div>`}
function renderAccountDashboard(body,model,{local=false}={}){
  const heroImage=model.avatar?`<img src="${escape(model.avatar)}" alt="${escape(model.name)} profile reference">`:`<div class="account-avatar-empty">${icon('avatar','No profile image')}<span>Add a character reference</span></div>`;
  const stats=[['take',model.takes,'Creations'],['style-pack',model.styles.length,'Style Packs'],['characters',model.characters,'Characters'],['favorite',model.favorites,'Favorites'],['projects',model.projects,'Projects'],['clock',`${model.hours}h`,'Time Creating']];
  body.innerHTML=`<div class="account-dashboard"><header class="account-title"><div class="account-spark">${icon('spark')}</div><div><h1>Account Hub</h1><p>Your creations. Your progress. Your space.</p></div><span class="account-note">Ideas live better here.</span></header>${local?'<div class="account-mode">Local workspace · Connect Supabase to sync this dashboard across devices.</div>':''}<section class="account-top"><article class="account-profile panel"><div class="account-profile-image">${heroImage}<div class="account-profile-shade"></div><strong>${escape(model.name)}</strong></div><div class="account-profile-copy"><span class="account-kicker">${model.cloud?'CLOUD CREATOR':'LOCAL CREATOR'}</span><h2>${escape(model.name)}</h2><p>${state.character?.identity?.occupation?escape(state.character.identity.occupation):'Create characters. Shape stories.'}</p><dl><div><dt>${icon('calendar')} Member since</dt><dd>${escape(model.memberSince?new Date(model.memberSince).toLocaleDateString(undefined,{month:'short',year:'numeric'}):'Today')}</dd></div><div><dt>${icon('take')} Total creations</dt><dd>${model.takes}</dd></div><div><dt>${icon('style-pack')} Style packs</dt><dd>${model.styles.length}</dd></div><div><dt>${icon('characters')} Characters</dt><dd>${model.characters}</dd></div></dl><div class="account-profile-actions"><button id="accountEdit">${icon('edit')} Edit Character</button>${model.cloud?`<button id="accountSignOut">${icon('logout')} Sign out</button>`:''}</div><p id="accountActionMessage" role="status"></p></div></article><section class="account-stats panel"><header><h2>Creative Stats</h2><span>All time</span></header><div>${stats.map(([glyph,value,label])=>`<article><span>${icon(glyph)}</span><strong>${value}</strong><small>${label}</small></article>`).join('')}</div></section></section><section class="account-middle"><article class="account-activity panel"><header><h2>Activity Overview</h2><span>Last 14 days</span></header><div class="activity-chart" aria-label="Creation activity for the last 14 days">${accountBars(model.activity)}</div></article><article class="account-usage panel"><header><h2>Style Pack Usage</h2><span>All time</span></header><div class="usage-body">${styleDonut(model.styles)}<ul>${model.styles.map(item=>`<li><i style="--legend:${item.color}"></i><span>${escape(item.name)}</span><b>${item.percent}%</b></li>`).join('')||'<li><span>No styles used yet</span></li>'}</ul></div></article></section><section class="account-bottom"><article class="account-recent panel"><header><h2>Recent Creations</h2><button data-account-go="create">View Studio ${icon('forward')}</button></header><div>${model.recent.length?model.recent.map((take,index)=>{const snap=take.stateSnapshot||{},scene=snap.scene?.name||'Character study',pack=snap.styleMix?.influences?.[0]?.packId;return `<article class="creation-card"><div>${take.image?`<img src="${escape(take.image)}" alt="${escape(scene)}">`:`<span>${icon('take','Creation without an image')}</span>`}</div><b>${escape(scene)}</b><small>${escape(STYLE_PACK_LIST.find(item=>item.id===pack)?.name||'PromptForge')} · ${escape(accountDate(take.createdAt)||'Recent')}</small></article>`}).join(''):'<div class="account-empty"><b>Your recent creations will appear here.</b><span>Create a Take in Studio to begin your gallery.</span></div>'}</div></article><article class="account-quick panel"><header><h2>Quick Actions</h2></header><div><button data-account-go="create">${icon('generate')}<span><b>Create New</b><small>Start a generation</small></span>${icon('forward')}</button><button data-account-go="style-packs">${icon('style-pack')}<span><b>Browse Style Packs</b><small>Explore and mix styles</small></span>${icon('forward')}</button><button data-account-go="library">${icon('library')}<span><b>Open Library</b><small>View reusable content</small></span>${icon('forward')}</button></div></article></section><footer class="account-quote">${icon('spark')}<span>“</span><p>A creative mind is a place to explore.</p><small>Keep creating.</small></footer></div>`;
  document.querySelectorAll('[data-account-go]').forEach(button=>button.onclick=()=>goWorkspace(button.dataset.accountGo));$('accountEdit')?.addEventListener('click',()=>{goWorkspace('create');setTimeout(()=>openCore($('userControl')),0)});
}
async function renderAccountWorkspace(view){const meta=workspaceMeta.account;view.innerHTML=`<div id="accountBody"><div class="panel account-loading"><h2>${icon('refresh')} Loading workspace…</h2><p>Checking your creations and profile.</p></div></div>`;const body=$('accountBody');if(!window.promptforgeSupabase){renderAccountDashboard(body,accountViewModel({}),{local:true});return}const user=await currentUser(window.promptforgeSupabase).catch(error=>{console.error('[Account]',error);return null});if(!user){body.innerHTML=`<div class="account-auth panel"><div>${icon('profile','Account')}</div><h1>Welcome to your Account Hub</h1><p>Sign in to sync characters, creations and creative progress.</p><form id="accountSignIn" class="drawer-form"><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="primary" type="submit">Sign in</button><p id="accountAuthMessage" role="status"></p></form><button id="accountLocal">Continue with local workspace</button></div>`;body.querySelector('#accountLocal').onclick=()=>renderAccountDashboard(body,accountViewModel({}),{local:true});body.querySelector('#accountSignIn').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget),message=$('accountAuthMessage');message.textContent='Signing in…';const result=await window.promptforgeSupabase.auth.signInWithPassword({email:String(form.get('email')),password:String(form.get('password'))});if(result.error){message.textContent=result.error.message;return}render()};return}const summary=await cloudStore.getSummary(user.id).catch(error=>({error}));if(summary.error){body.innerHTML=`<div class="panel"><h2>${icon('error')} Account data unavailable</h2><p>${escape(summary.error.message||'Supabase returned an error.')}</p></div>`;return}renderAccountDashboard(body,accountViewModel(summary,user));$('accountSignOut').onclick=async()=>{await window.promptforgeSupabase.auth.signOut();render()}}

const coverageLabel=status=>({poor:'Needs content',low:'Early',good:'Growing',healthy:'Healthy'}[status]||status);
function libraryRegistry(){const registry=createLibraryRegistry({stylePacks:STYLE_PACK_LIST,scenes:SCENE_OPTIONS,state});validateLibraryRegistry(registry);return registry}
function selectedLibrary(registry){let category=registry.find(item=>item.id===(ui.libraryCategory||'interests'))||registry[0];let family=category.families.find(item=>item.id===ui.libraryFamily)||category.families[0]||null;return {category,family}}
function libraryCount(category){return `${category.entryCount} ${category.entryCount===1?'entry':'entries'}`}
function librarySource(family){if(family.fixture)return 'Starter structure';const sources=[...new Set((family.entries||[]).map(entry=>entry.source))];return sources.length===1?`${sources[0][0].toUpperCase()}${sources[0].slice(1)} content`:'Mixed sources'}
function renderLibraryWorkspace(view){
  const registry=libraryRegistry(),filter=ui.libraryFilter||'all',query=ui.libraryQuery||'',results=searchLibrary(registry,query,filter);let {category,family}=selectedLibrary(registry);
  if(!results.some(item=>item.id===category.id)){category=results[0]||category;family=category.families[0]||null}
  const allEntries=registry.reduce((sum,item)=>sum+item.entryCount,0),starterCount=registry.flatMap(item=>item.families).filter(item=>item.fixture).length,focusCoverage=['interests','hobbies'].map(id=>{const report=coverageDiagnostics(registry,id);return `${id[0].toUpperCase()+id.slice(1)} ${coverageLabel(report.category)}`}).join(' · ');
  const categoryRows=registry.filter(item=>filter==='all'||item.id===filter).map(item=>`<button class="library-category ${item.id===category.id?'selected':''}" data-library-category="${item.id}" aria-pressed="${item.id===category.id}"><span class="library-icon">${escape(item.icon)}</span><span><b>${escape(item.label)}</b><small>${libraryCount(item)} · ${item.familyCount} ${item.familyCount===1?'family':'families'}</small></span><em class="coverage-dot ${item.coverage}" title="${coverageLabel(item.coverage)}"></em></button>`).join('');
  const families=(results.find(item=>item.id===category.id)?.families||[]).map(item=>{const coverage=coverageFor(item.entries.length);return `<button class="library-family ${family?.id===item.id?'selected':''}" data-library-family="${item.id}" aria-pressed="${family?.id===item.id}"><span class="family-glyph">${escape(category.icon)}</span><span class="family-title"><b>${escape(item.label)}</b><small>${item.entries.length} ${item.entries.length===1?'entry':'entries'}</small></span><p>${escape(item.description)}</p><span class="family-foot"><small>${escape(librarySource(item))}</small><em class="coverage-label ${coverage}">${coverageLabel(coverage)}</em></span></button>`}).join('');
  view.innerHTML=`<header class="library-head"><div><div class="eyebrow">CONTENT FOUNDATION · SCHEMA ${LIBRARY_SCHEMA_VERSION}</div><h1>▤ Library</h1><p>Reusable character, world and expression content—kept clear by source.</p></div><div class="library-head-actions"><button id="libraryExport">Export manifest</button><button id="libraryImport">Import preview</button><input id="libraryImportFile" type="file" accept="application/json" hidden></div></header><div class="library-toolbar"><label class="library-search"><span>⌕</span><input id="librarySearch" type="search" value="${escape(query)}" placeholder="Search categories, families and entries" autocomplete="off"></label><label class="library-filter"><span class="sr-only">Category filter</span><select id="libraryFilter"><option value="all">All categories</option>${registry.map(item=>`<option value="${item.id}" ${filter===item.id?'selected':''}>${escape(item.label)}</option>`).join('')}</select></label><span class="library-total">${allEntries} wired entries · ${focusCoverage}</span></div><div class="library-layout"><aside class="library-categories" aria-label="Library categories"><div class="library-pane-title"><b>Content categories</b><small>${registry.length} domains</small></div>${categoryRows}</aside><section class="library-browser"><header class="library-browser-head"><div><span class="library-kicker">${escape(category.layer==='starter'?'STARTER FOUNDATION':category.layer.toUpperCase())}</span><h2>${escape(category.icon)} ${escape(category.label)}</h2><p>${escape(category.description)}</p></div><span class="coverage-chip ${category.coverage}">${coverageLabel(category.coverage)}</span></header><div class="library-subnav"><b>Families</b><span>${category.familyCount} groups · ${libraryCount(category)}</span></div><div class="library-families">${families||`<div class="library-empty"><b>No matching content</b><span>Try a broader search or another category.</span></div>`}</div></section><aside class="library-detail" aria-live="polite">${renderLibraryDetail(category,family)}</aside></div>`;
  bindLibraryWorkspace(registry,category,family);
}
function renderLibraryDetail(category,family){if(!family)return '<div class="library-empty"><b>Select a family</b><span>Details and entries will appear here.</span></div>';const tab=ui.libraryTab||'overview',entries=family.entries||[],subcategories=family.subcategories||[];const tabs=['overview','entries','related'];let content='';if(tab==='entries')content=entries.length?`<div class="library-entry-list">${entries.map(entry=>`<div><span>${escape(entry.label)}</span><small>${escape(entry.source)}</small></div>`).join('')}</div>`:'<div class="library-empty compact"><b>No entries yet</b><span>This family is ready for content enrichment.</span></div>';else if(tab==='related')content=`<div class="detail-copy"><p>Links are soft context only: they can inform recommendations without forcing a hobby onto a character.</p><div class="detail-tags">${(family.tags||[]).map(tag=>`<span>${escape(tag)}</span>`).join('')||'<span>Unmapped</span>'}</div></div>`;else content=`<div class="detail-copy"><p>${escape(family.description)}</p><div class="detail-tags">${[...(family.tags||[]),librarySource(family)].map(tag=>`<span>${escape(tag)}</span>`).join('')}</div></div>${subcategories.length?`<section class="subcategory-section"><header><b>Subcategories</b><small>${subcategories.length}</small></header>${subcategories.map(row=>`<div><span>${escape(row.label)}</span><small>${row.entryCount} ${row.entryCount===1?'entry':'entries'}</small></div>`).join('')}</section>`:''}`;return `<header class="detail-head"><span class="detail-icon">${escape(category.icon)}</span><div><span class="library-kicker">${family.fixture?'STARTER STRUCTURE':'LIVE CONTENT'}</span><h2>${escape(family.label)}</h2><p>${entries.length} ${entries.length===1?'entry':'entries'} · ${escape(librarySource(family))}</p></div></header><div class="detail-tabs" role="tablist">${tabs.map(name=>`<button role="tab" aria-selected="${tab===name}" data-library-tab="${name}">${name[0].toUpperCase()+name.slice(1)}${name==='entries'?` (${entries.length})`:''}</button>`).join('')}</div>${content}<section class="gemini-foundation"><div><span>✦</span><b>Enrichment operations</b><p>Prepare structured candidates for review; core data is never mutated.</p></div><select id="libraryExpandMode" aria-label="Enrichment operation">${ENRICHMENT_OPERATIONS.map(name=>`<option>${name}</option>`).join('')}</select><button id="libraryExpand">Prepare review</button></section><footer class="detail-provenance"><span>Source layers</span><b>core + user + imported/generated review</b></footer>`}
function bindLibraryWorkspace(registry,category,family){
  document.querySelectorAll('[data-library-category]').forEach(button=>button.onclick=()=>{ui.libraryCategory=button.dataset.libraryCategory;ui.libraryFamily=null;ui.libraryTab='overview';render()});document.querySelectorAll('[data-library-family]').forEach(button=>button.onclick=()=>{ui.libraryCategory=category.id;ui.libraryFamily=button.dataset.libraryFamily;ui.libraryTab='overview';render()});document.querySelectorAll('[data-library-tab]').forEach(button=>button.onclick=()=>{ui.libraryTab=button.dataset.libraryTab;render()});
  $('librarySearch').oninput=event=>{ui.libraryQuery=event.target.value;const caret=event.target.selectionStart;render();requestAnimationFrame(()=>{const input=$('librarySearch');input.focus();input.setSelectionRange(caret,caret)})};$('libraryFilter').onchange=event=>{ui.libraryFilter=event.target.value;ui.libraryCategory=event.target.value==='all'?ui.libraryCategory:event.target.value;ui.libraryFamily=null;render()};
  $('libraryExpand')?.addEventListener('click',()=>{const prepared=prepareEnrichmentOperation($('libraryExpandMode').value,category.id,family?.id,registry);toast(`${prepared.operation} prepared for review—core library unchanged`)});$('libraryExport').onclick=()=>exportLibraryManifest(registry);$('libraryImport').onclick=()=>$('libraryImportFile').click();$('libraryImportFile').onchange=event=>previewLibraryImport(event.target.files[0]);
}
function exportLibraryManifest(registry){const payload={schemaVersion:LIBRARY_SCHEMA_VERSION,exportedAt:new Date().toISOString(),mode:'layered-manifest',categories:registry};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='promptforge-library-manifest.json';link.click();URL.revokeObjectURL(url);toast('Library manifest exported')}
async function previewLibraryImport(file){if(!file)return;try{const parsed=JSON.parse(await file.text());if(!parsed.schemaVersion||!Array.isArray(parsed.categories))throw new Error('invalid');toast('Import preview validated—nothing was merged')}catch{toast('That file is not a PromptForge Library manifest')}finally{$('libraryImportFile').value=''}}
function goWorkspace(name){activeWorkspace=name;localStorage.setItem('promptforge-workspace',name);render()}

function inspectorPayload(resolved){return {resolver:resolved.resolver,normalizedMix:resolved.styleMix.normalizedInfluences,resolved:resolved.resolved,provenance:Object.fromEntries(Object.entries(resolved.provenance.categories).map(([category,data])=>[category,{selection:data.selection,candidates:data.candidates.map(candidate=>({id:candidate.id,score:candidate.score,support:candidate.support,seedFactor:candidate.seedFactor,contributors:candidate.contributions.map(item=>item.packName),adjustments:candidate.adjustments}))}]))}}
function inspect(){if(!state.character){toast('Create a Character Core before resolving');return}try{const resolved=resolveStudioState(state),output=JSON.stringify(inspectorPayload(resolved),null,2);$('inspectorOutput').textContent=output;$('drawerInspectorOutput').textContent=output;setDrawer('inspector',true,$('inspectBtn'))}catch(error){toast(error.message)}}
function showConsole(){const panel=$('console'),prompt=state.lastPrompt;panel.classList.remove('hidden');panel.innerHTML=`✓ Character Core preserved<br>✓ Style Mix normalized and resolved<br>✓ Context compatibility scored<br>✓ Locks and overrides applied<br><br>✨ ${escape(prompt?.compiler?.provider||'local')} preview ready<br><pre class="prompt-preview">${escape(prompt?.text||'')}</pre><div class="drawer-actions"><button id="promptCopy" type="button">Copy prompt</button><button id="promptExport" type="button">Export JSON</button></div>`;$('promptCopy').onclick=copyPrompt;$('promptExport').onclick=exportPrompt}
async function compileOnly(){if(!state.character){toast('Create a Character Core before compiling');return}try{setForge('generating');const result=await compilePromptPreview(state,{gemini:window.promptforgeGemini,localCompiler:MockCompiler});state=result.state;if(result.fallbackError){console.error('[Gemini] prompt generation failed',result.fallbackError);toast(`Gemini unavailable (${result.fallbackError.message}); local preview used`)}showConsole();render();setForge('success');setTimeout(()=>setForge('idle'),motionOK()?420:0);toast(`${result.provider} prompt ready`)}catch(error){setForge('error');toast(error.message)}}

async function runGeneration(kind='generate'){
  if(!state.character){toast('Create a Character Core first');return}const serial=++generationSerial;ui.busy=true;ui.forge=kind==='surprise'?'surprise':'generating';
  try{state={...state,generationOptions:{...state.generationOptions,seed:`promptforge-take-${state.takes.length+1}`}};state=compileGeneration(state,MockCompiler);state=createTake(state,kind);render();showConsole();const sequence=['identity','expression','interests','wardrobe','scene','photography','lighting','generation'];for(const name of sequence){if(serial!==generationSerial)return;const panel=document.querySelector(`[data-panel="${name}"]`);if(!panel||panel.classList.contains('locked'))continue;panel.classList.add('updating');panel.setAttribute('aria-busy','true');if(motionOK())await wait(85);panel.classList.remove('updating');panel.removeAttribute('aria-busy')}ui.forge='success';setForge('success');ui.busy=false;renderGenerationOptions();if(motionOK())await wait(420);if(serial===generationSerial){ui.forge='idle';setForge('idle')}toast(kind==='surprise'?'A surprising new Take is ready':'New Take ready')}
  catch(error){ui.busy=false;ui.forge='error';setForge('error');toast(error.message)}
}
function surprise(){const index=state.takes.length;if(!state.character)state=createCharacter(state,{name:['Nova','Ari','Sora','Rowan'][index%4],location:['Tokyo','London','Seoul','New York'][index%4],occupation:['Creative technologist','Editorial photographer','Architect','Indie designer'][index%4]});const options=state.generationOptions;if(!options.keepStyleMix){const a=STYLE_PACK_LIST[index%STYLE_PACK_LIST.length],b=STYLE_PACK_LIST[(index+5)%STYLE_PACK_LIST.length];state={...state,styleMix:{...state.styleMix,influences:[{packId:a.id,weight:65},{packId:b.id,weight:35}]}}}if(!options.keepScene)state={...state,scene:SCENE_OPTIONS[(index*3+2)%SCENE_OPTIONS.length]};runGeneration('surprise')}

function commandItems(){const base=[{label:'Create or edit character',group:'Character',run:()=>openCore($('commandTrigger'))},{label:'Generate Take',group:'Forge',disabled:!state.character,run:()=>runGeneration('generate')},{label:'Surprise Me',group:'Forge',run:surprise},{label:'Open Style Mix',group:'Studio',run:()=>{renderStyleDrawer();setDrawer('style',true,$('stylePanel'))}},{label:'Open Scene browser',group:'Studio',run:()=>{renderSceneDrawer();setDrawer('scene',true,$('sceneBtn'))}},{label:'Open Takes',group:'Studio',run:()=>{$('takesList').scrollIntoView({behavior:motionOK()?'smooth':'auto'})}},{label:'Inspect resolution',group:'Tools',disabled:!state.character,run:inspect},{label:ui.focus?'Exit Focus Mode':'Enter Focus Mode',group:'View',disabled:!state.character,run:toggleFocus},{label:'Import Character',group:'Character',run:()=>$('importFile').click()},{label:'Export Character',group:'Character',disabled:!state.character,run:exportCharacter},];const packs=STYLE_PACK_LIST.map(pack=>({label:pack.name,group:'Style Pack',run:()=>{renderStyleDrawer();setDrawer('style',true,$('stylePanel'));requestAnimationFrame(()=>{const input=$('drawerPackSearch');input.value=pack.name;input.dispatchEvent(new Event('input'))})}}));const scenes=SCENE_OPTIONS.map(scene=>({label:scene.name,group:'Scene',run:()=>{state={...state,scene};render();toast(`${scene.name} selected`)}}));return [...base,...packs,...scenes]}
function openCommand(){closeDrawer();const palette=$('commandPalette');previousFocus=document.activeElement;palette.hidden=false;document.body.classList.add('command-open');if(!$('commandClose'))palette.querySelector('.command-shell').insertAdjacentHTML('afterbegin','<button id="commandClose" class="command-close" type="button" aria-label="Close command palette">×</button>');$('commandClose').onclick=closeCommand;$('commandInput').value='';ui.commandIndex=0;renderCommands();renderIcons();requestAnimationFrame(()=>$('commandInput').focus())}
function closeCommand(){const palette=$('commandPalette');if(palette.hidden)return;palette.hidden=true;document.body.classList.remove('command-open');previousFocus?.focus?.()}
function filteredCommands(){const query=$('commandInput').value.trim().toLowerCase();return commandItems().filter(item=>!query||`${item.label} ${item.group}`.toLowerCase().includes(query))}
function enhanceWardrobeForm(){const form=$('wardrobeForm');if(form.dataset.slotsReady)return;form.dataset.slotsReady='true';form.innerHTML=`<p class="drawer-intro">Fill any slots you want. Empty slots are valid; one-piece outfits do not need a top or bottom.</p><div class="drawer-two-up">${['head','top','bottom','onePiece','shoes','outerwear','accessory'].map(slot=>`<label>${slot==='onePiece'?'One piece':slot[0].toUpperCase()+slot.slice(1)}<input name="slot-${slot}" placeholder="Optional"></label>`).join('')}</div><button type="button" id="wardrobeSuggestBtn">Suggest missing pieces</button><label class="lock-control"><input name="locked" type="checkbox"> Lock manual wardrobe</label><div class="drawer-actions"><button type="button" data-close-drawer>Cancel</button><button class="primary" type="submit">Save Wardrobe</button></div>`;form.querySelector('#wardrobeSuggestBtn').onclick=()=>{const suggestions=suggestWardrobePieces(state,{seed:state.generationOptions.seed});for(const [slot,value] of Object.entries(suggestions)){const input=form.elements[`slot-${slot}`];if(input&&!input.value)input.value=value}};form.querySelector('[data-close-drawer]').onclick=closeDrawer}
function enhanceWardrobeChoices(){const form=$('wardrobeForm');if(!form||form.querySelector('#wardrobeChoices'))return;const list=document.createElement('datalist');list.id='wardrobeChoices';list.innerHTML=WARDROBE_CHOICES.map(choice=>`<option value="${escape(choice)}">`).join('');form.append(list);form.querySelectorAll('input[name^="slot-"]').forEach(input=>input.setAttribute('list','wardrobeChoices'))}
function renderCommands(){const items=filteredCommands();ui.commandIndex=Math.max(0,Math.min(ui.commandIndex,items.length-1));$('commandResults').innerHTML=items.length?items.map((item,index)=>`<button role="option" aria-selected="${index===ui.commandIndex}" class="command-item ${index===ui.commandIndex?'active':''}" data-command-index="${index}" ${item.disabled?'disabled':''}><span>${escape(item.label)}</span><small>${escape(item.group)}</small></button>`).join(''):'<p class="command-empty">No matching command.</p>';document.querySelectorAll('[data-command-index]').forEach(button=>button.onclick=()=>executeCommand(Number(button.dataset.commandIndex)))}
function executeCommand(index=ui.commandIndex){const item=filteredCommands()[index];if(!item||item.disabled)return;closeCommand();item.run()}
function toggleFocus(){if(!state.character){toast('Create a character before entering Focus Mode');return}ui.focus=!ui.focus;applyAmbience();save();toast(ui.focus?'Focus Mode on':'Focus Mode off')}
function exportCharacter(){if(!state.character)return;const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${state.character.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'character'}.json`;link.click();URL.revokeObjectURL(url);toast('Character exported')}
function exportPrompt(){const prompt=state.lastPrompt||state.compiledPrompts?.[0];if(!prompt){toast('Compile a prompt first');return}const url=URL.createObjectURL(new Blob([JSON.stringify(prompt,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='promptforge-prompt.json';link.click();URL.revokeObjectURL(url);toast('Prompt exported')}
async function copyPrompt(){const prompt=state.lastPrompt||state.compiledPrompts?.[0];if(!prompt){toast('Compile a prompt first');return}try{await navigator.clipboard.writeText(prompt.text);toast('Prompt copied')}catch{toast('Copy is unavailable in this browser')}}
function enhanceCoreTemplates(){const form=$('coreForm');if(!form||form.querySelector('#characterTemplate'))return;const label=document.createElement('label'),select=document.createElement('select');select.id='characterTemplate';select.innerHTML=`<option value="">Start manually</option>${CHARACTER_TEMPLATES.map(item=>`<option value="${item.id}">${item.name}</option>`).join('')}`;label.textContent='Starting template';label.append(select);form.querySelector('fieldset')?.prepend(label);for(const [id,choices] of [['traitChoices',APPEARANCE_CHOICES.traits],['interestChoices',INTEREST_CHOICES]]){const list=document.createElement('datalist');list.id=id;list.innerHTML=choices.map(choice=>`<option value="${escape(choice)}">`).join('');form.append(list)}form.traits.setAttribute('list','traitChoices');form.interests.setAttribute('list','interestChoices');select.onchange=()=>{const item=CHARACTER_TEMPLATES.find(row=>row.id===select.value);form.dataset.template=item?.id||'';if(!item)return;for(const [key,value] of Object.entries({name:item.character.name,age:item.character.age,location:item.character.location,occupation:item.character.occupation,traits:item.character.traits.join(', '),interests:item.character.interests.join(', ')}))form.elements[key].value=value;};form.addEventListener('submit',()=>{const template=CHARACTER_TEMPLATES.find(item=>item.id===form.dataset.template);if(!template||coreMode!=='new')return;setTimeout(()=>{const direction=templateDirection(template);state={...state,scene:direction.scene,wardrobe:normalizeWardrobe({source:'manual',items:direction.wardrobe}),visualSettings:{...state.visualSettings,lighting:{...state.visualSettings.lighting,behaviour:direction.lighting}},styleMix:{...state.styleMix,influences:direction.styleMix},selectedTake:null,dirty:true};render();toast(`${template.name} direction applied`)})})}
async function importCharacter(file){try{const parsed=JSON.parse(await file.text());state=parsed.character?restoreState(JSON.stringify(parsed)):createCharacter(blankState(),parsed);goWorkspace('create');toast('Character imported')}catch{toast('That file is not a valid PromptForge character')}}

function bindGlobal(){
  ensureSceneDrawer();ensurePhotoDrawer();ensureInterestsDrawer();enhanceWardrobeForm();enhanceWardrobeChoices();document.querySelectorAll('[data-close-drawer]').forEach(button=>button.onclick=closeDrawer);$('overlay').onclick=closeDrawer;
  $('coreReferenceBtn').onclick=()=>{if(!state.character){toast('Save the Character Core first');return}$('referenceFile').click()};$('referenceFile').onchange=event=>{const file=event.target.files?.[0];if(!file||!state.character)return;const reader=new FileReader();reader.onload=async()=>{state=addReference(state,{source:file.name,image:reader.result});const reference=state.character.references.at(-1);if(window.promptforgeSupabase){const user=await currentUser(window.promptforgeSupabase).catch(()=>null);if(user){try{const uploaded=await cloudStore.uploadReference(file,user.id);reference.storagePath=uploaded.path;toast('Reference attached and uploaded')}catch(error){console.error('[Cloud Store] Reference upload failed',error);toast('Reference attached locally; cloud upload failed')}}}$('coreReferenceStatus').textContent=`${state.character.references.length} reference${state.character.references.length===1?'':'s'} attached`;renderReferenceList();save();render();openCore()};reader.readAsDataURL(file)};
  $('wardrobeForm').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget),slots=Object.fromEntries(['head','top','bottom','onePiece','shoes','outerwear','accessory'].map(slot=>[slot,String(data.get(`slot-${slot}`)||'').trim()])),items=Object.values(slots).filter(Boolean);state={...state,wardrobe:normalizeWardrobe({...state.wardrobe,source:'manual',items,slots,locked:data.get('locked')==='on'}),dirty:true,selectedTake:null};closeDrawer();render();toast('Wardrobe saved')};
  $('photoForm').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget);state={...state,visualSettings:{...state.visualSettings,photography:{...state.visualSettings.photography,shotType:String(data.get('shotType')),lens:String(data.get('lens')),angle:String(data.get('angle')),locked:data.get('locked')==='on'},lighting:{...state.visualSettings.lighting,behaviour:String(data.get('behaviour')),colourTreatment:String(data.get('colourTreatment'))}},dirty:true,selectedTake:null};closeDrawer();render();toast('Photography saved')};
  $('interestsForm').onsubmit=event=>{event.preventDefault();const interests=String(new FormData(event.currentTarget).get('interests')||'').split(',').map(item=>item.trim()).filter(Boolean);state={...state,interestState:{...state.interestState,characterInterests:interests},character:state.character?{...state.character,interests}:state.character,dirty:true,selectedTake:null};closeDrawer();render();toast('Interests saved')};
  $('coreForm').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget),list=name=>String(data.get(name)||'').split(',').map(item=>item.trim()).filter(Boolean),input={name:String(data.get('name')).trim(),age:Number(data.get('age')),location:String(data.get('location')).trim(),occupation:String(data.get('occupation')).trim()};const next=coreMode==='new'?createCharacter({...state,character:null,activeCharacterId:null},input):state.character?editCharacter(state,input):createCharacter(state,input);const generated=event.currentTarget.dataset.personality?JSON.parse(event.currentTarget.dataset.personality):null;const structured={...normalizePersonality(next.character.personality),...generated,traits:list('traits'),voice:String(data.get('voice')||generated?.voice||'Observant and warm').trim(),motivations:list('motivations'),contradictions:list('contradictions')};state={...next,character:{...next.character,personality:structured,interests:list('interests')},characters:(next.characters||[]).map(item=>item.id===next.character.id?{...item,personality:structured,interests:list('interests')}:item),interestState:{...next.interestState,characterInterests:list('interests')},selectedTake:coreMode==='new'?null:next.selectedTake};closeDrawer();render();toast(coreMode==='new'?'Character created':'Character Core saved')};
  document.querySelectorAll('[data-workspace]').forEach(button=>button.onclick=()=>goWorkspace(button.dataset.workspace));
  $('compileBtn').onclick=compileOnly;$('inspectBtn').onclick=inspect;$('seedInput').value=state.generationOptions.seed;$('seedInput').onchange=event=>mutate(current=>({...current,generationOptions:{...current.generationOptions,seed:event.target.value||'promptforge-1'}}),{clearTake:false});
  $('commandTrigger').onclick=openCommand;$('focusBtn').onclick=toggleFocus;$('userControl').onclick=event=>openCore(event.currentTarget);$('themeBtn').onclick=()=>{ui.theme=ui.theme==='dark'?'light':'dark';applyAmbience();renderIcons();save();toast(`${ui.theme[0].toUpperCase()+ui.theme.slice(1)} theme`) };$('commandInput').oninput=()=>{ui.commandIndex=0;renderCommands()};$('importFile').onchange=event=>{const file=event.target.files[0];if(file)importCharacter(file);event.target.value=''};
}

document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('commandPalette').hidden?openCommand():closeCommand();return}if(!$('commandPalette').hidden){if(event.key==='Escape'){event.preventDefault();closeCommand()}else if(event.key==='ArrowDown'){event.preventDefault();ui.commandIndex=Math.min(ui.commandIndex+1,filteredCommands().length-1);renderCommands()}else if(event.key==='ArrowUp'){event.preventDefault();ui.commandIndex=Math.max(ui.commandIndex-1,0);renderCommands()}else if(event.key==='Enter'){event.preventDefault();executeCommand()}else if(event.key==='Tab')trapFocus(event,$('commandPalette'));return}if(activeDrawer){if(event.key==='Escape'){event.preventDefault();closeDrawer()}else if(event.key==='Tab')trapFocus(event,$(activeDrawer+'Drawer'))}});
document.addEventListener('visibilitychange',()=>document.documentElement.toggleAttribute('data-page-hidden',document.hidden));
enhanceCoreTemplates();
render();
